mapper.select:
SELECT I.INQUIRY_ID AS inquiryId, I.INQUIRY_TYPE AS inquiryType, I.MEMBER_NO AS memberNo, M.MEMBER_NAME AS memberName, M.EMAIL AS memberEmail, I.TITLE AS title, I.BODY AS body, I.REF_TYPE AS refType, I.REF_ID AS refId, TRIM(I.STATUS_CD) AS statusCd, I.ANSWER AS answer, I.APPLY_DATE AS applyDate, I.ANSWER_DATE AS answerDate, I.REG_DATE AS regDate, R.RESV_NO AS resvNo, R.STATUS_CD AS resvStatusCd, R.TOTAL_AMOUNT AS totalAmount, S.NAME AS stayName FROM TB_INQUIRY I JOIN TB_MEMBER M ON M.MEMBER_NO = I.MEMBER_NO JOIN TB_RESERVATION R ON R.RESV_ID = I.REF_ID AND R.RESV_TYPE = 'STAY' LEFT JOIN TB_STAY S ON S.STAY_ID = TO_NUMBER(R.TARGET_ID) WHERE I.REF_TYPE = 'RESV' AND I.INQUIRY_TYPE = 'RESERVE' AND TO_NUMBER(R.TARGET_ID) = #{stayId}
AND TRIM(I.STATUS_CD) IN ('APPROVED', 'DONE')
AND TRIM(I.STATUS_CD) = 'REJECTED'
AND TRIM(I.STATUS_CD) = #{statusCd}
ORDER BY I.REG_DATE DESC, I.INQUIRY_ID DESC

SELECT I.INQUIRY_ID AS inquiryId, I.INQUIRY_TYPE AS inquiryType, I.MEMBER_NO AS memberNo, M.MEMBER_NAME AS memberName, M.EMAIL AS memberEmail, I.TITLE AS title, I.BODY AS body, I.REF_TYPE AS refType, I.REF_ID AS refId, TRIM(I.STATUS_CD) AS statusCd, I.ANSWER AS answer, I.APPLY_DATE AS applyDate, I.ANSWER_DATE AS answerDate, I.REG_DATE AS regDate FROM TB_INQUIRY I JOIN TB_MEMBER M ON M.MEMBER_NO = I.MEMBER_NO WHERE (I.REF_TYPE IS NULL OR I.REF_TYPE <> 'RESV')
AND TRIM(I.STATUS_CD) = #{statusCd}
ORDER BY I.REG_DATE DESC, I.INQUIRY_ID DESC
